*{box-sizing:border-box} :root{--ink:#e7dfc9;--muted:#989687;--gold:#d5a755;--rust:#bb674a;--panel:rgba(15,20,19,.78);--line:rgba(232,218,185,.2)} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#171b17;color:var(--ink);font-family:'IBM Plex Mono',monospace;touch-action:none} #game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#9c8061} #game{display:block;width:100%;height:100%}.grain{position:absolute;inset:0;pointer-events:none;opacity:.1;z-index:2;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.94' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:18px 30px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(13,17,15,.8),transparent)}.brand{display:flex;gap:12px;align-items:center}.brand-mark{font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:-1px;color:#eddfbd;border:1px solid rgba(232,218,185,.45);padding:4px 7px}.brand-mark span{color:var(--gold)}.brand div{display:flex;flex-direction:column;gap:3px}.brand b{font:700 13px 'Barlow Condensed',sans-serif;letter-spacing:2px}.brand small{font-size:8px;letter-spacing:1px;color:#bbb4a1}.top-right{display:flex;gap:16px;align-items:center}.region-tag{font-size:9px;letter-spacing:1.6px;color:#d9c9a7}.region-tag i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c66d4e;margin-right:8px;box-shadow:0 0 8px #c66d4e}.icon-btn{border:1px solid var(--line);background:rgba(0,0,0,.2);color:var(--ink);width:32px;height:32px;font-size:15px;cursor:pointer}.mission-card{position:absolute;top:98px;left:30px;width:300px;padding:16px 18px 14px;background:var(--panel);border:1px solid var(--line);border-left:2px solid var(--gold);z-index:3;backdrop-filter:blur(8px)}.eyebrow,.mission-meta,.status-label,.status-foot,.weapon-switch,.xp-row,.xp-foot{font-size:8px;letter-spacing:1.2px;color:#a6a18f}.eyebrow{display:flex;align-items:center;gap:7px}.tiny-star{color:var(--gold);font-size:12px}.line{height:1px;flex:1;background:var(--line)}#objective-count{color:#d5a755}.mission-card h1{font:700 20px 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:12px 0 4px;color:#f0e5cc}.mission-card p{font-size:10px;color:#c2bdad;margin:0 0 14px;line-height:1.5}.mission-progress{height:2px;background:#3b4039;margin-bottom:9px}.mission-progress span{display:block;height:100%;width:18%;background:var(--gold);transition:width .4s}.mission-meta{display:flex;justify-content:space-between;font-size:7px;color:#8e9185}.compass{position:absolute;z-index:3;top:28px;left:50%;transform:translateX(-50%);width:178px;text-align:center;color:#ddd3bd;text-shadow:0 2px 6px #161614}.compass-head{display:flex;justify-content:space-between;align-items:center;font-size:9px;color:#bbb6a8}.compass-head b{font-size:13px;color:var(--gold)}.compass-tick{margin:6px auto 4px;height:8px;width:1px;background:var(--gold)}.compass-marker{font-size:9px;color:var(--gold);letter-spacing:1px}.compass-marker span{font-size:7px;margin-left:4px}.crosshair{position:absolute;z-index:3;top:50%;left:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.85}.crosshair i{position:absolute;background:#eee7d7;box-shadow:0 1px 3px #222}.crosshair i:nth-child(1){width:1px;height:5px;left:8px;top:0}.crosshair i:nth-child(2){width:1px;height:5px;left:8px;bottom:0}.crosshair i:nth-child(3){width:5px;height:1px;left:0;top:8px}.crosshair i:nth-child(4){width:5px;height:1px;right:0;top:8px}.crosshair b{position:absolute;width:2px;height:2px;border-radius:100%;background:#d9b469;top:8px;left:8px}.hitmarker{position:absolute;z-index:4;left:50%;top:50%;font-size:30px;color:#f3dec0;transform:translate(-50%,-50%);opacity:0;transition:opacity .08s;text-shadow:0 0 8px #a54131}.hitmarker.show{opacity:1}.toast{position:absolute;z-index:5;left:50%;top:24%;transform:translateX(-50%);font-size:10px;letter-spacing:1.2px;color:#efdfbb;background:rgba(16,20,18,.8);border:1px solid var(--line);padding:9px 16px;opacity:0;transition:opacity .25s;pointer-events:none}.toast.show{opacity:1}.interact-prompt{position:absolute;left:50%;top:57%;transform:translateX(-50%);z-index:3;background:rgba(14,18,16,.8);border:1px solid rgba(214,171,94,.6);padding:10px 15px;color:#f2d89e;font-size:10px;letter-spacing:1px;display:none;white-space:nowrap}.damage-vignette{position:absolute;inset:0;z-index:2;pointer-events:none;box-shadow:inset 0 0 0 0 rgba(150,28,21,0);transition:box-shadow .15s}.damage-vignette.pulse{box-shadow:inset 0 0 90px 35px rgba(150,28,21,.58)}.bottom-hud{position:absolute;z-index:3;left:30px;right:30px;bottom:24px;display:grid;grid-template-columns:180px minmax(270px,420px) 140px;gap:14px;align-items:end}.status-panel,.weapon-panel,.xp-panel{padding:12px 14px;background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(7px)}.status-label,.status-foot,.xp-row{display:flex;justify-content:space-between}.status-label{font-size:9px;color:#d2c8b3}.status-label span:last-child{font-size:12px;color:#e5d19f}.bar{height:4px;background:rgba(237,228,206,.17);margin:7px 0}.bar i{display:block;height:100%;width:100%;background:#c8a05b;transition:width .2s}.status-foot{font-size:7px}.status-foot b{color:#91a17d;font-weight:400}.weapon-panel{border-bottom:2px solid var(--gold)}.weapon-info{display:flex;align-items:center;justify-content:space-between}.weapon-info small{color:#b0aa99;font-size:8px;letter-spacing:1.4px}.weapon-info h2{font:700 18px 'Barlow Condensed',sans-serif;letter-spacing:1.6px;margin:2px 0 1px;color:#f1e7d0}.weapon-info #weapon-type{font-size:7px;letter-spacing:1px;color:#a9a18f}.ammo{display:flex;align-items:baseline;gap:5px}.ammo b{font:600 29px 'Barlow Condensed',sans-serif;color:#f4dfb2}.ammo span{font-size:11px;color:#85877d}.ammo span:last-child{font-size:17px}.weapon-switch{border-top:1px solid var(--line);margin-top:9px;padding-top:8px;display:flex;gap:12px;font-size:7px;white-space:nowrap}.weapon-switch kbd{font:inherit;color:#d4a756;border:1px solid rgba(214,171,94,.5);padding:1px 3px;margin-right:3px}.weapon-switch .reload-tip{margin-left:auto;color:#aaa493}.xp-panel{padding:12px}.xp-row{font-size:8px}.xp-row b{color:var(--gold);font-size:11px}.xp-bar{height:3px}.xp-bar i{width:26%;background:#9da979}.xp-foot{font-size:6px;display:flex;justify-content:space-between}.xp-foot span{color:#9ba282;letter-spacing:2px}.overlay{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(13,17,15,.53);backdrop-filter:blur(3px)}.overlay.hidden{display:none}.start-card{width:min(430px,calc(100% - 34px));padding:36px 39px 24px;background:linear-gradient(145deg,rgba(25,29,25,.97),rgba(17,21,19,.97));border:1px solid rgba(221,199,154,.35);box-shadow:0 25px 100px #10120f;text-align:center;position:relative}.start-card:before,.start-card:after{content:'';position:absolute;width:30px;height:30px;border-color:#c39148}.start-card:before{left:-1px;top:-1px;border-left:2px solid;border-top:2px solid}.start-card:after{right:-1px;bottom:-1px;border-right:2px solid;border-bottom:2px solid}.start-kicker{font-size:8px;letter-spacing:2px;color:#d2aa60}.start-kicker span{color:#8e8b80}.logo-title{font:800 63px/.8 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#e6d9bb;margin:20px auto 14px;text-shadow:3px 4px 0 rgba(122,75,43,.5)}.logo-title i{font-style:normal;color:var(--gold)}.logo-title span{font-size:10px;vertical-align:top;color:#b8aa8a}.start-copy{font-size:10px;color:#aca898;letter-spacing:.3px;margin:0 0 22px}.start-rule{height:1px;background:linear-gradient(90deg,transparent,#82734f,transparent)}.loadout{display:flex;flex-direction:column;gap:6px;margin:17px 0 19px;font-size:8px;color:#d7c6a4;letter-spacing:.6px}.loadout span{font-size:7px;color:#8f9085;letter-spacing:1.4px;margin-bottom:2px}.start-btn{width:100%;padding:14px 15px;background:#bb8140;color:#171912;border:0;font:700 12px 'Barlow Condensed',sans-serif;letter-spacing:1.7px;cursor:pointer;box-shadow:inset 0 1px rgba(255,255,255,.25);transition:background .2s}.start-btn:hover{background:#d5a455}.start-btn span{float:right;font-size:17px;line-height:10px}.controls-copy{display:flex;justify-content:center;flex-wrap:wrap;gap:11px;margin:18px 0 0;color:#888a7f;font-size:7px;letter-spacing:.5px}.touch-copy{display:none;color:#86877b;font-size:8px;margin-top:12px}.pause-card{width:min(400px,calc(100% - 32px));padding:35px;background:rgba(19,23,20,.96);border:1px solid var(--line);text-align:center}.pause-card h2{font:700 42px 'Barlow Condensed',sans-serif;margin:12px 0;color:#e8ddc1;letter-spacing:2px}.pause-card p{font-size:10px;color:#a8a596;margin:0 0 22px}.mobile-controls{display:none}.mobile-rotate{display:none}
@media(max-width:800px){.topbar{padding:14px 16px;height:60px}.brand b{font-size:11px}.brand small{font-size:7px}.region-tag{font-size:8px}.mission-card{left:16px;top:72px;width:245px;padding:12px}.mission-card h1{font-size:17px}.mission-card p{font-size:9px;margin-bottom:10px}.mission-meta{font-size:6px}.bottom-hud{left:14px;right:14px;bottom:13px;grid-template-columns:118px minmax(180px,1fr);gap:8px}.status-panel,.weapon-panel{padding:9px 10px}.xp-panel{display:none}.weapon-info h2{font-size:16px}.weapon-switch{gap:7px;font-size:6px}.weapon-switch .reload-tip{display:none}.status-label{font-size:8px}.status-foot{font-size:6px}.compass{top:23px}.mobile-controls{display:block;position:absolute;z-index:5;inset:0;pointer-events:none}.move-pad{position:absolute;left:17px;bottom:105px;width:112px;height:112px;pointer-events:auto;touch-action:none}.stick-ring{position:absolute;inset:8px;border:1px solid rgba(236,225,199,.36);border-radius:50%;background:rgba(15,19,17,.21);display:grid;place-items:center}.stick-ring:before{content:'';position:absolute;width:52px;height:52px;border:1px solid rgba(236,225,199,.15);border-radius:50%}#stick-knob{width:40px;height:40px;border-radius:50%;background:rgba(206,172,111,.48);border:1px solid rgba(240,222,183,.55);box-shadow:0 2px 9px #111;transform:translate(0,0)}.move-pad small{position:absolute;bottom:-3px;left:38px;color:#d8cfb9;font-size:7px;letter-spacing:1.4px;text-shadow:0 1px 5px #111}.look-hint{position:absolute;left:50%;bottom:120px;transform:translateX(-50%);font-size:7px;letter-spacing:1.6px;color:rgba(235,224,201,.48)}.mobile-actions{position:absolute;right:16px;bottom:104px;width:132px;height:142px;pointer-events:none}.touch-btn,.fire-btn,.weapon-cycler button{pointer-events:auto;color:#f0e5ce;background:rgba(15,19,17,.53);border:1px solid rgba(235,223,194,.37);font:600 9px 'IBM Plex Mono',monospace;touch-action:none}.touch-btn{position:absolute;width:39px;height:39px;border-radius:50%}.use-btn{left:0;top:3px;font-size:7px}.reload-btn{right:1px;top:3px;font-size:18px}.fire-btn{position:absolute;right:18px;top:50px;width:68px;height:68px;border-radius:50%;background:rgba(157,65,46,.58);border:1px solid rgba(239,185,143,.7);font-size:10px;letter-spacing:1px;box-shadow:0 0 18px rgba(116,40,29,.28)}.weapon-cycler{pointer-events:auto;position:absolute;bottom:0;left:2px;right:2px;display:flex;align-items:center;justify-content:space-between;height:28px;background:rgba(15,19,17,.58);border:1px solid rgba(235,223,194,.25)}.weapon-cycler button{border:0;background:transparent;font-size:18px;width:28px;height:26px}.weapon-cycler span{font-size:8px;color:#e8d2a4;letter-spacing:1px}.touch-copy{display:block}.controls-copy{display:none}.start-card{padding:28px 28px 20px}.logo-title{font-size:55px}.mission-card{top:70px}.interact-prompt{top:60%;font-size:8px}.crosshair{top:49%}}
@media(max-width:520px){.region-tag{display:none}.mission-card{width:215px}.mission-card p{max-width:180px}.weapon-switch span:nth-child(3){display:none}.bottom-hud{grid-template-columns:94px minmax(160px,1fr)}.status-foot span:first-child{display:none}.status-panel{padding:8px}.ammo b{font-size:25px}.weapon-info h2{font-size:14px}.weapon-info #weapon-type{font-size:6px}.compass{top:18px}.topbar{height:53px}.brand-mark{font-size:18px}.start-card{padding:24px 20px 18px}.logo-title{font-size:50px}.start-copy{font-size:9px}}
@media(max-height:500px) and (orientation:landscape){.mission-card{top:65px;padding:9px 12px}.mission-card h1{margin:7px 0 2px;font-size:15px}.mission-card p{margin-bottom:7px}.bottom-hud{bottom:8px}.mobile-controls .move-pad{bottom:82px;transform:scale(.82);transform-origin:left bottom}.mobile-actions{bottom:78px;transform:scale(.82);transform-origin:right bottom}.touch-copy{margin-top:7px}.start-card{padding:17px 25px}.logo-title{font-size:47px;margin:12px auto}.loadout{margin:10px}.controls-copy{margin-top:10px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

// DUST & IRON — a compact, entirely procedural Mojave FPS.
const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xb4a184);
scene.fog = new THREE.Fog(0xb4a184, 44, 145);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 180);
camera.rotation.order = 'YXZ';
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.5));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;

scene.add(new THREE.HemisphereLight(0xe4d7b6, 0x554539, 2.15));
const sun = new THREE.DirectionalLight(0xffdfaa, 3.1);
sun.position.set(-32, 54, 25);
scene.add(sun);
const fill = new THREE.DirectionalLight(0x9ca99e, .75); fill.position.set(24, 18, -35); scene.add(fill);
const mat = (color, roughness=.9, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  sand: mat(0x9b7856), road: mat(0x76604a), rock: mat(0x625448), lightRock: mat(0xa58c69),
  dark: mat(0x282c28), metal: mat(0x393e3b,.48,.72), rust: mat(0x87523b), wood: mat(0x66513a),
  cloth: mat(0x575b48), skin: mat(0x92745a), cactus: mat(0x475343), canvas: mat(0xb59a6b),
  concrete: mat(0x777368), glass: new THREE.MeshStandardMaterial({color:0x75837d, roughness:.25, metalness:.25})
};
const boxGeo = new THREE.BoxGeometry(1,1,1);
function box(parent, name, size, position, material, rotation){ const m=new THREE.Mesh(boxGeo,material); m.name=name; m.scale.set(...size);m.position.set(...position);if(rotation)m.rotation.set(...rotation);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m; }
function cylinder(parent,r1,r2,h,position,material,segments=8,rotation){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(...position);if(rotation)m.rotation.set(...rotation);m.castShadow=true;parent.add(m);return m;}
function sphere(parent,r,pos,material,scale=[1,1,1]){const m=new THREE.Mesh(new THREE.SphereGeometry(r,10,8),material);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;parent.add(m);return m;}

// Broad baked-looking terrain, a dusty highway and distant mesas.
const ground = new THREE.Mesh(new THREE.PlaneGeometry(260,260,1,1), mats.sand);
ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
const road = new THREE.Mesh(new THREE.PlaneGeometry(7,150),mats.road);road.rotation.x=-Math.PI/2;road.position.set(0,-.09,-28);scene.add(road);
for(let i=0;i<38;i++){
  const z=16-i*3.65, x=(i%2?1:-1)*(3.65+(i%4)*.12);
  box(scene,'road stripe',[.08,.015,1.7],[x,-.07,z],mat(0xc3a777));
}
function mesa(x,z,sx,sy,sz,color){const m=new THREE.Mesh(new THREE.ConeGeometry(1,1,5),mat(color));m.scale.set(sx,sy,sz);m.position.set(x,sy*.5-0.1,z);m.rotation.y=.35+(x%2)*.2;scene.add(m);}
mesa(-49,-73,24,20,18,0x806950);mesa(50,-77,28,25,24,0x77634f);mesa(-77,-34,22,18,28,0x907454);mesa(82,-24,24,19,25,0x816a53);mesa(30,-105,34,25,20,0x8e765d);

// Rusted relay compound and roadside debris.
function makeTower(){
 const g=new THREE.Group();g.position.set(0,0,-49);scene.add(g);
 const steel=mats.metal, beam=boxGeo;
 for(const x of [-1.25,1.25])for(const z of [-1.1,1.1]){
  const leg=box(g,'tower leg',[.14,11,.14],[x,5.5,z],steel);leg.rotation.z=x*.08;
 }
 for(const y of [1.5,4,6.5,9,10.8]){
  box(g,'tower brace',[2.7,.12,.12],[0,y,-1.1],steel);box(g,'tower brace',[2.7,.12,.12],[0,y,1.1],steel);
  box(g,'tower side brace',[.12,.12,2.4],[-1.25,y,0],steel);box(g,'tower side brace',[.12,.12,2.4],[1.25,y,0],steel);
 }
 for(const y of [2.75,5.25,7.75]){const d=box(g,'cross brace',[.1,2.7,.1],[0,y,-1.15],steel);d.rotation.z=.65;const d2=box(g,'cross brace',[.1,2.7,.1],[0,y,1.15],steel);d2.rotation.z=-.65;}
 box(g,'relay hut',[3.4,2.3,3],[0,1.15,0],mats.concrete);
 box(g,'relay door',[.78,1.6,.06],[0,.8,-1.55],mats.dark);
 box(g,'antenna deck',[3.1,.16,2.8],[0,10.9,0],mats.rust);
 cylinder(g,.04,.04,5,[0,13.2,0],steel,8);
 const dish=new THREE.Mesh(new THREE.SphereGeometry(1,12,8,0,Math.PI*2,0,Math.PI/2),mat(0xaaa18a,.5,.5));dish.position.set(.9,12.4,.15);dish.rotation.z=-.5;dish.scale.set(.9,.22,.9);g.add(dish);
 const beacon=new THREE.PointLight(0xe5a44d,0,9);beacon.position.set(0,12.5,0);g.add(beacon);g.userData.beacon=beacon;
 for(let x=-1;x<=1;x+=2)box(g,'warning panel',[.38,.75,.04],[x*1.35,1.8,-1.54],mats.rust);
 g.userData.activate=()=>{beacon.intensity=8;};return g;
}
const relay=makeTower();
function shack(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,'shack',[5,3.2,4],[0,1.6,0],mats.wood);box(g,'roof',[5.8,.24,4.8],[0,3.25,0],mats.rust);box(g,'door',[.9,2,.07],[1.35,1,-2.05],mats.dark);box(g,'window',[1,.75,.08],[-1.2,2,-2.06],mats.glass);return g;}
shack(-12,-5);
function barrel(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,.42,.42,.92,[0,.46,0],x%2?mats.rust:mats.metal,12);for(let y of [.2,.7])cylinder(g,.44,.44,.065,[0,y,0],mats.dark,12);}
for(const p of [[-5,-12],[4,-23],[-9,-35],[8,-42],[-14,-20],[14,-7]])barrel(...p);
function rock(x,z,s){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(1,0),x%2?mats.rock:mats.lightRock);m.position.set(x,s*.48,z);m.scale.set(s*1.2,s*.8,s);m.rotation.set(.15*x,.2*z,.1*x);m.castShadow=true;scene.add(m);}
for(let i=0;i<54;i++){const side=i%2?1:-1;const x=side*(7+Math.random()*31),z=18-Math.random()*105;rock(x,z,.35+Math.random()*1.7);}
function cactus(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,.22*s,.27*s,2.5*s,[0,1.25*s,0],mats.cactus,7);cylinder(g,.12*s,.13*s,.95*s,[.35*s,1.15*s,0],mats.cactus,7,[0,0,Math.PI/2.5]);cylinder(g,.12*s,.13*s,.8*s,[.51*s,1.55*s,0],mats.cactus,7,[0,0,-Math.PI/2.5]);cylinder(g,.12*s,.13*s,.85*s,[-.34*s,.95*s,0],mats.cactus,7,[0,0,-Math.PI/2.3]);cylinder(g,.12*s,.13*s,.72*s,[-.52*s,1.35*s,0],mats.cactus,7,[0,0,Math.PI/2.5]);}
for(let i=0;i<24;i++)cactus((i%2?1:-1)*(9+Math.random()*28),16-Math.random()*100,.55+Math.random()*.65);

const player={pos:new THREE.Vector3(0,0,8),yaw:0,pitch:0,health:100,ammo:0,reserve:0,xp:0,kills:0,started:false,paused:false,done:false,moveX:0,moveY:0,lastDamage:0};
camera.position.set(player.pos.x,1.68,player.pos.z);scene.add(camera);

input.newString:
camera.position.set(player.pos.x,1.68,player.pos.z);scene.add(camera);

const weapons=[
 {name:'RANGER AR-16',short:'AR-16',type:'5.56MM · SERVICE CARBINE',capacity:24,ammo:24,reserve:96,damage:34,rate:145,reload:1550,spread:.007,kind:'rifle'},
